#!/usr/bin/env node
/**
 * Live Database Schema Parity Verifier.
 *
 * Compares the live database schema (information_schema.columns) against the canonical
 * schema snapshot generated by Drizzle Kit in drizzle/meta/.
 *
 * Catches missing tables and missing columns before they cause runtime 500/503 errors.
 */

import fs from "node:fs";
import path from "node:path";
import { config } from "dotenv";
import postgres from "postgres";

config({ path: ".env.local" });
config();

const isCI = Boolean(process.env.CI || process.env.GITHUB_ACTIONS);

const candidates = [];

if (isCI) {
  if (process.env.DATABASE_URL?.trim()) {
    candidates.push({ name: "DATABASE_URL (Pooler)", url: process.env.DATABASE_URL.trim() });
  }
  if (process.env.DIRECT_URL?.trim()) {
    candidates.push({ name: "DIRECT_URL (Direct)", url: process.env.DIRECT_URL.trim() });
  }
} else {
  if (process.env.DIRECT_URL?.trim()) {
    candidates.push({ name: "DIRECT_URL (Direct)", url: process.env.DIRECT_URL.trim() });
  }
  if (process.env.DATABASE_URL?.trim()) {
    candidates.push({ name: "DATABASE_URL (Pooler)", url: process.env.DATABASE_URL.trim() });
  }
}

if (candidates.length === 0) {
  console.error("❌ Error: Neither DIRECT_URL nor DATABASE_URL is configured.");
  process.exit(1);
}

// 1. Locate the latest Drizzle snapshot
const journalPath = path.resolve("drizzle/meta/_journal.json");
if (!fs.existsSync(journalPath)) {
  console.error(`❌ Error: Drizzle journal not found at ${journalPath}`);
  process.exit(1);
}

const journal = JSON.parse(fs.readFileSync(journalPath, "utf8"));
if (!journal.entries || journal.entries.length === 0) {
  console.error("❌ Error: No entries found in drizzle/meta/_journal.json");
  process.exit(1);
}

const latestEntry = journal.entries[journal.entries.length - 1];
const prefix = latestEntry.tag.split("_")[0];
const snapshotPath = path.resolve(`drizzle/meta/${prefix}_snapshot.json`);

if (!fs.existsSync(snapshotPath)) {
  console.error(`❌ Error: Snapshot file not found at ${snapshotPath}`);
  process.exit(1);
}

const snapshot = JSON.parse(fs.readFileSync(snapshotPath, "utf8"));
const expectedTables = snapshot.tables || {};

console.log(`📋 Verifying schema against snapshot: ${prefix}_snapshot.json (${latestEntry.tag})`);

// 2. Connect to the database
let activeSql = null;

for (const candidate of candidates) {
  const client = postgres(candidate.url, {
    max: 1,
    prepare: false,
    idle_timeout: 20,
    connect_timeout: 10,
  });

  try {
    await client`SELECT 1`;
    activeSql = client;
    console.log(`✓ Connected to database via ${candidate.name}.`);
    break;
  } catch (probeError) {
    await client.end({ timeout: 2 }).catch(() => {});
    const cause = probeError?.cause || probeError;
    const msg = cause?.message || probeError?.message || String(probeError);
    console.warn(`⚠️ Connection via ${candidate.name} failed: ${msg}`);
  }
}

if (!activeSql) {
  console.error("❌ Could not connect to any configured database.");
  process.exit(1);
}

// 3. Inspect public schema columns and constraints
try {
  const rows = await activeSql`
    SELECT table_name, column_name, data_type, is_nullable
    FROM information_schema.columns 
    WHERE table_schema = 'public';
  `;

  const constraints = await activeSql`
    SELECT conrelid::regclass::text as table_name, conname, contype
    FROM pg_constraint
    WHERE connamespace = 'public'::regnamespace;
  `;

  const liveColumns = new Set(rows.map((r) => `${r.table_name}.${r.column_name}`));
  const liveTables = new Set(rows.map((r) => r.table_name));
  const liveConstraints = new Set(constraints.map((c) => `${c.table_name}:${c.conname}`));
  const tablesWithPk = new Set(constraints.filter((c) => c.contype === "p").map((c) => c.table_name));

  const missingTables = [];
  const missingColumns = [];
  const missingConstraints = [];
  let totalCheckedColumns = 0;
  let totalCheckedConstraints = 0;

  for (const [, tableData] of Object.entries(expectedTables)) {
    const tableName = tableData.name;
    if (!liveTables.has(tableName)) {
      missingTables.push(tableName);
      continue;
    }

    // Verify Primary Key
    const hasPkColumn = Object.values(tableData.columns || {}).some((c) => c.primaryKey);
    const hasCompositePk = Object.keys(tableData.compositePrimaryKeys || {}).length > 0;
    if ((hasPkColumn || hasCompositePk) && !tablesWithPk.has(tableName)) {
      missingConstraints.push(`${tableName}: missing PRIMARY KEY`);
    }

    // Verify Unique Constraints
    for (const [, ucData] of Object.entries(tableData.uniqueConstraints || {})) {
      totalCheckedConstraints++;
      const ucName = ucData.name;
      if (!liveConstraints.has(`${tableName}:${ucName}`)) {
        missingConstraints.push(`${tableName}: missing UNIQUE constraint "${ucName}"`);
      }
    }

    for (const [, colData] of Object.entries(tableData.columns || {})) {
      totalCheckedColumns++;
      const colName = colData.name;
      if (!liveColumns.has(`${tableName}.${colName}`)) {
        missingColumns.push(`${tableName}.${colName} (expected type: ${colData.type})`);
      }
    }
  }

  if (missingTables.length > 0 || missingColumns.length > 0 || missingConstraints.length > 0) {
    console.error("\n❌ Database Schema Parity Check FAILED!");
    if (missingTables.length > 0) {
      console.error(`\nMissing Tables (${missingTables.length}):`);
      for (const t of missingTables) console.error(`  - ${t}`);
    }
    if (missingColumns.length > 0) {
      console.error(`\nMissing Columns (${missingColumns.length}):`);
      for (const c of missingColumns) console.error(`  - ${c}`);
    }
    if (missingConstraints.length > 0) {
      console.error(`\nMissing Constraints (${missingConstraints.length}):`);
      for (const c of missingConstraints) console.error(`  - ${c}`);
    }
    console.error("\nPlease generate and run the appropriate migration before proceeding.");
    process.exit(1);
  }

  const tableCount = Object.keys(expectedTables).length;
  console.log(`✅ Schema Parity Verified: All ${tableCount} tables, ${totalCheckedColumns} columns, and ${totalCheckedConstraints} constraints verified in the database.`);
  process.exit(0);
} catch (err) {
  console.error("❌ Unexpected error during schema verification:", err);
  process.exit(1);
} finally {
  if (activeSql) {
    await activeSql.end({ timeout: 5 });
  }
}
